107|#[test]
108|fn test_find_roots_only() {
109|    let dir = setup_workspace();
110|
111|    write(
112|        dir.path().join("parent.md"),
113|        indoc! {"
114|            # Parent
115|
116|            [child](child)
117|        "},
118|    )
119|    .unwrap();
120|
121|    write(dir.path().join("child.md"), "# Child\n\nChild content.").unwrap();
122|    write(dir.path().join("orphan.md"), "# Orphan\n\nNo references.").unwrap();
123|
124|    let (stdout, stderr, success) = run_iwe(dir.path(), &["--roots", "-f", "json"]);
125|
126|    assert!(success, "stderr: {}", stderr);
127|
128|    let parsed: serde_json::Value = serde_json::from_str(&stdout).expect("valid JSON");
129|    let results = parsed["results"].as_array().unwrap();
130|
131|    let keys: Vec<&str> = results.iter().map(|r| r["key"].as_str().unwrap()).collect();
132|
133|    assert!(keys.contains(&"parent"), "parent should be a root");
134|    assert!(keys.contains(&"orphan"), "orphan should be a root");
135|    assert!(!keys.contains(&"child"), "child should NOT be a root");
136|}
216|fn test_find_limit() {
217|    let dir = setup_workspace();
218|
219|    for i in 1..=10 {
220|        write(
221|            dir.path().join(format!("doc{}.md", i)),
222|            format!("# Document {}\n\nContent.", i),
223|        )
224|        .unwrap();
225|    }
226|
227|    let (stdout, stderr, success) = run_iwe(dir.path(), &["--limit", "3", "-f", "json"]);
228|
229|    assert!(success, "stderr: {}", stderr);
230|
231|    let parsed: serde_json::Value = serde_json::from_str(&stdout).expect("valid JSON");
232|    assert_eq!(parsed["total"], 10, "total should be 10");
233|    assert_eq!(parsed["results"].as_array().unwrap().len(), 3, "should return only 3 results");
